    const ai=`<p class="cl-muted">点击具体客户，再展开交付计费、客户预算或单项参数。客户推理成本率、训练预算和Google采购份额没有直接量化证据。</p><div id="clContractEvidence">${Object.keys(labels).map(c=>customerItem(c,contract,audit,economics)).join('')}</div>${evidenceItem('ai:common','跨客户共同参数与假设依据',globalControls(['global.capacityMultiplier','global.utilizationMultiplier','global.netPriceMultiplier','global.customerBudgetMultiplier','global.googleShareMultiplier'])+tableEvidence(audit,'audit:ai',[0,1,2,3,4]))}${evidenceItem('ai:upstream','客户与GPU供应侧材料如何进入模型',(upstream[0]?.outerHTML||'')+(upstream[2]?.outerHTML||'')+(upstream[3]?.outerHTML||''))}`;
